<COVER>        final List<CronParserField> sortedExpression = cronDefinition.getFieldDefinitions().stream()
<COVER>                .map(this::toCronParserField)
<COVER>                .sorted(CronParserField.createFieldTypeComparator())
<COVER>                .collect(Collectors.toList());

