import com.cronutils.model.field.parser.FieldParser;
import com.cronutils.model.field.parser.FieldParserContext;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

public class CronParserTest {

    @Test
    public void testParseExtendedQuartzCronWithOptionalYearAndDayOfYear() {
        // Arrange
        CronDefinition cronDefinition = CronDefinitionBuilder.defineCron()
                .withSeconds()
                .and()
                .withMinutes()
                .and()
                .withHours()
                .and()
                .withDayOfMonth()
                    .supportsQuestionMark()
                .and()
                .withMonth()
                .and()
                .withDayOfWeek()
                    .supportsQuestionMark()
                .and()
                .withYear()
                    .optional()
                .and()
                .withDayOfYear()
                    .optional()
                .and()
                .instance();

        CronParser parser = new CronParser(cronDefinition);
        String expression = "0 0 0 ? * ? 2017 *";

        // Act
        Cron cron = parser.parse(expression);

        // Assert
        assertNotNull(cron, "Cron object should not be null");

        CronField yearField = cron.retrieve(CronFieldName.YEAR);
        assertNotNull(yearField, "Year field should be present");
        assertEquals("2017", yearField.getExpression(), "Year field should be 2017");

        CronField dayOfYearField = cron.retrieve(CronFieldName.DAY_OF_YEAR);
        assertNotNull(dayOfYearField, "Day of year field should be present");
        assertEquals("*", dayOfYearField.getExpression(), "Day of year field should be *");

        // Additional assertions to verify other fields can be added here
    }

}

