public class BetweenDayOfWeekValueGeneratorTest {
    private BetweenDayOfWeekValueGenerator valueGenerator;
    private WeekDay mondayDoWValue;

    @BeforeEach
    public void setUp() {
        CronField cronField = new CronField(
            CronFieldName.DAY_OF_WEEK,
            new Between(new IntegerFieldValue(1), new IntegerFieldValue(5)),
            FieldConstraintsBuilder.instance().forField(CronFieldName.DAY_OF_WEEK).createConstraintsInstance()
        );
        mondayDoWValue = new WeekDay(1, true);
        valueGenerator = new BetweenDayOfWeekValueGenerator(cronField, 2016, 2, mondayDoWValue);
    }

    @Test
    public void testGenerateCandidatesNotIncludingIntervalExtremes() {
        final List<Integer> expectedValues = Arrays.asList(
            2, 3, 4, 5, 8, 9, 10, 11, 12,
            15, 16, 17, 18, 19, 22, 23, 24,
            25, 26, 29, 30, 31
        );
        final List<Integer> actualValues = valueGenerator.generateCandidatesNotIncludingIntervalExtremes(1, 32);

        // Check that all expected values are present
        assertTrue(actualValues.containsAll(expectedValues), "The generated values should contain all expected values.");

        // Check that specific values are included
        assertTrue(actualValues.contains(29), "The value 29 should be included in the generated values.");
        assertTrue(actualValues.contains(30), "The value 30 should be included in the generated values.");

        // Check that the list is sorted in ascending order
        assertTrue(isSorted(actualValues), "The generated values should be sorted in ascending order.");

        // Check that the size matches the expected number of values
        assertEquals(expectedValues.size(), actualValues.size(), "The number of generated values should match the expected count.");
    }

    private boolean isSorted(List<Integer> list) {
        return IntStream.range(1, list.size())
                .allMatch(i -> list.get(i - 1) <= list.get(i));
    }
}

