<COVER>        final List<Integer> candidates = new ArrayList<>();
<COVER>        for (final FieldExpression expression : and.getExpressions()) {
<COVER>            candidates.add(
<COVER>                    function.apply(
<COVER>                                createCandidateGeneratorInstance(new CronField(cronField.getField(), expression, cronField.getConstraints()))
                    )
            );
