<COVER>        final List<Integer> filteredCandidates = new ArrayList<>();
<COVER>        for (final Integer candidate : candidates) {
<COVER>            if (candidate >= 0) {
<COVER>                filteredCandidates.add(candidate);
            }
        }
<COVER>        Collections.sort(filteredCandidates);
<COVER>        return filteredCandidates;
    }

    private FieldValueGenerator createCandidateGeneratorInstance(final CronField cronField) {
<COVER>        final FieldExpression expression = cronField.getExpression();
<COVER>        if (expression instanceof Always) {
            return new AlwaysFieldValueGenerator(cronField);
