    public EveryFieldValueGenerator(final CronField cronField) {
<COVER>        super(cronField);

<COVER>        final Every every = (Every) cronField.getExpression();
<COVER>        final FieldExpression everyExpression = every.getExpression();
<COVER>        if (everyExpression instanceof Between) {
